const express = require('express');
const { z } = require('zod');
const { StructuredTool } = require('@langchain/core/tools');
const { authenticateStaff } = require('../middleware/auth');
const { EhrRepository } = require('../repositories/ehr');

const app = express();
app.use(express.json());

class PatientMedicationHistoryTool extends StructuredTool {
  name = 'get_patient_medications';
  description = 'Retrieves active and historical prescriptions for a patient record';
  schema = z.object({
    patientRecordId: z.string().uuid()
  });

  constructor(practitionerId) {
    super();
    this.practitionerId = practitionerId;
  }

  async _call({ patientRecordId }) {
    // Verify practitioner is assigned to the patient's care team
    const isAssigned = await EhrRepository.isPractitionerAssigned(this.practitionerId, patientRecordId);
    if (!isAssigned) {
      return JSON.stringify({ error: 'Access denied: Practitioner not assigned to patient' });
    }
    const records = await EhrRepository.findMedicationsByPatientId(patientRecordId);
    return JSON.stringify(records);
  }
}

app.post('/api/copilot/tools/patient-medications', authenticateStaff, async (req, res) => {
  const { toolInput } = req.body;
  try {
    const medTool = new PatientMedicationHistoryTool(req.user.id);
    const result = await medTool.invoke(toolInput);
    const parsed = JSON.parse(result);
    if (parsed.error) return res.status(403).json(parsed);
    res.json({ data: parsed });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.listen(8118);
